/**
 * @param {number[]} nums
 * @param {number[][]} queries
 * @return {number}
 */
var xorAfterQueries = function(nums, queries) {
    const mod = 10 ** 9 + 7;

    for (const [l, r, k, v] of queries) {
        let idx = l;

        while (idx <= r) {
            nums[idx] = (nums[idx] * v) % mod;
            idx += k;
        }
    }

    return nums.reduce((acc, el) => acc ^ el, 0);
};
